            'الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۚ وَهُوَ الْعَزِيزُ الْغَفُورُ',
            'الَّذِي خَلَقَ سَبْعَ سَمَاوَاتٍ طِبَاقًا ۖ مَّا تَرَىٰ فِي خَلْقِ الرَّحْمَٰنِ مِن تَفَاوُتٍ ۖ فَارْجِعِ الْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ',
            'ثُمَّ ارْجِعِ الْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ الْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ',
            'وَلَقَدْ زَيَّنَّا السَّمَاءَ الدُّنْيَا بِمَصَابِيحَ وَجَعَلْنَاهَا رُجُومًا لِّلشَّيَاطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ السَّعِيرِ',
            'وَلِلَّذِينَ كَفَرُوا بِرَبِّهِمْ عَذَابُ جَهَنَّمَ ۖ وَبِئْسَ الْمَصِيرُ',
            'إِذَا أُلْقُوا فِيهَا سَمِعُوا لَهَا شَهِيقًا وَهِيَ تَفُورُ',
            'تَكَادُ تَمَيَّزُ مِنَ الْغَيْظِ ۖ كُلَّمَا أُلْقِيَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَا أَلَمْ يَأْتِكُمْ نَذِيرٌ',
            'قَالُوا بَلَىٰ قَدْ جَاءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ اللَّهُ مِن شَيْءٍ إِنْ أَنتُمْ إِلَّا فِي ضَلَالٍ كَبِيرٍ',
            'وَقَالُوا لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِي أَصْحَابِ السَّعِيرِ',
            'فَاعْتَرَفُوا بِذَنبِهِمْ فَسُحْقًا لِّأَصْحَابِ السَّعِيرِ',
            'إِنَّ الَّذِينَ يَخْشَوْنَ رَبَّهُم بِالْغَيْبِ لَهُمْ مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ',
            'وَأَسِرُّوا قَوْلَكُمْ أَوِ اجْهَرُوا بِهِ ۖ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ',
            'أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ اللَّطِيفُ الْخَبِيرُ',
            'هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِ ۖ وَإِلَيْهِ النُّشُورُ',
            'أَأَمِنتُم مَّن فِي السَّمَاءِ أَن يَخِسِفَ بِكُمُ الْأَرْضَ فَإِذَا هِيَ تَمُورُ',
            'أَمْ أَمِنتُم مَّن فِي السَّمَاءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًا ۖ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ',
            'وَلَقَدْ كَذَّبَ الَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ',
            'أَوَلَمْ يَرَوْا إِلَى الطَّيْرِ فَوْقَهُمْ صَافَّاتٍ وَيَقْبِضْنَ ۚ مَا يُمْسِكُهُنَّ إِلَّا الرَّحْمَٰنُ ۚ إِنَّهُ بِكُلِّ شَيْءٍ بَصِيرٌ',
            'أَمَّن هَٰذَا الَّذِي هُوَ جُندٌ لَّكُمْ يَنصُرُكُم مِّن دُونِ الرَّحْمَٰنِ ۚ إِنِ الْكَافِرُونَ إِلَّا فِي غُرُورٍ',
            'أَمَّن هَٰذَا الَّذِي يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُ ۚ بَل لَّجُّوا فِي عُتُوٍّ وَنُفُورٍ',
            'أَفَمَن يَمْشِي مُكِبًّا عَلَىٰ وَجْهِهِ أَهْدَىٰ أَمَّن يَمْشِي سَوِيًّا عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ',
            'قُلْ هُوَ الَّذِي أَنشَأَكُمْ وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ ۖ قَلِيلًا مَّا تَشْكُرُونَ',
            'قُلْ هُوَ الَّذِي ذَرَأَكُمْ فِي الْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ',
            'وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَادِقِينَ',
            'قُلْ إِنَّمَا الْعِلْمُ عِندَ اللَّهِ وَإِنَّمَا أَنَا نَذِيرٌ مُّبِينٌ',
            'فَلَمَّا رَأَوْهُ زُلْفَةً سِيئَتْ وُجُوهُ الَّذِينَ كَفَرُوا وَقِيلَ هَٰذَا الَّذِي كُنتُم بِهِ تَدْعُونَ',
            'قُلْ أَرَأَيْتُمْ إِنْ أَهْلَكَنِيَ اللَّهُ وَمَن مَّعِيَ أَوْ رَحِمَنَا فَمَن يُجِيرُ الْكَافِرِينَ مِنْ عَذَابٍ أَلِيمٍ',
            'قُلْ هُوَ الرَّحْمَٰنُ آمَنَّا بِهِ وَعَلَيْهِ تَوَكَّلْنَا ۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِي ضَلَالٍ مُّبِينٍ',
            'قُلْ أَرَأَيْتُمْ إِنْ أَصْبَحَ مَاؤُكُمْ غَوْرًا فَمَن يَأْتِيكُم بِمَاءٍ مَّعِينٍ',
          ],
          versesEn: [
            'Blessed is He in whose hand is dominion, and He is over all things competent.',
            'He who created death and life to test you as to which of you is best in deed - and He is the Exalted in Might, the Forgiving.',
            'And who created seven heavens in layers. You do not see in the creation of the Most Merciful any inconsistency. So return your vision; do you see any breaks?',
            'Then return your vision twice again. Your vision will return to you humbled while it is not fatigued.',
            'And We have certainly beautified the nearest heaven with stars and have made them [as a means] for stoning the devils and have prepared for them the punishment of the Blaze.',
            'And for those who have disbelieved in their Lord is the punishment of Hell, and wretched is the destination.',
            'When they are thrown into it, they hear from it a [dreadful] inhaling while it seethes.',
            'It almost bursts with rage. Every time a company is thrown into it, its keepers ask them, "Did there not come to you a warner?"',
            'They will say, "Yes, there came to us a warner, but we denied and said, \'Allah has not sent down anything. You are not but in great error.\'"',
            'And they say, "If only we had been listening or reasoning, we would not be among the companions of the Blaze."',
            'So they acknowledged their sin, but far away is [forgiveness] from the companions of the Blaze.',
            'Indeed, those who fear their Lord unseen will have forgiveness and great reward.',
            'And conceal your speech or publicize it; indeed, He is Knowing of that within the breasts.',
            'Does He who created not know, while He is the Subtle, the Acquainted?',
            'It is He who made the earth tame for you - so walk among its slopes and eat of His provision. And to Him is the resurrection.',
            'Do you feel secure that He who is in the heaven will not cause the earth to swallow you? And suddenly it would convulse?',
            'Do you feel secure that He who is in the heaven will not send against you a storm of stones? Then you would know how [severe] was My warning.',
            'And already had those before them disbelieved, and how [terrible] was My reproach.',
            'Have they not seen the birds above them with wings spread and [sometimes] folded in? None holds them [aloft] except the Most Merciful. Indeed, He is, of all things, Seeing.',
            'Or who is it that could be an army for you to aid you other than the Most Merciful? The disbelievers are not but in delusion.',
            'Or who is it that will provide for you if He withholds His provision? Rather, they have persisted in pride and aversion.',
            'Then who will guide the one who walks on his face more rightly than one who walks on the straight way?',
            'Say, "It is He who has created you and made for you hearing and vision and hearts. Little do you give thanks."',
            'Say, "It is He who has dispersed you throughout the earth, and to Him you will be gathered."',
            'And they say, "When is this promise, if you should be truthful?"',
            'Say, "The knowledge is only with Allah. And I am only a clear warner."',
            'But when they see it approaching, the faces of those who have disbelieved will become distressed, and it will be said, "This is that for which you used to call for."',
            'Say, "Have you considered: whether Allah destroys me and those with me or has mercy upon us - who will protect the disbelievers from a painful punishment?"',
            'Say, "He is the Most Merciful; we have believed in Him, and upon Him we have relied. And you will come to know who it is that is in clear error."',
            'Say, "Have you considered: if your water were to become sunken [into the earth], then who could bring you water in a flowing stream?"' /* PASTE REST HERE */
            ],
          ),
          QuranSurah(
