            versesAr: [
              'إِنَّآ أَنزَلْنَـٰهُ فِى لَيْلَةِ ٱلْقَدْرِ',
              'وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ',
              'لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ',
              'تَنَزَّلُ ٱلْمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍۢ',
              'سَلَـٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ'
            ],
            versesEn: [
              'Indeed, ˹it is˺ We ˹Who˺ sent this ˹Quran˺ down on the Night of Glory.',
              'And what will make you realize what the Night of Glory is?',
              'The Night of Glory is better than a thousand months.',
              'That night the angels and the ˹holy˺ spirit descend, by the permission of their Lord, for every ˹decreed˺ matter.',
              'It is all peace until the break of dawn.'
            ],
          ),

          QuranSurah(
            id: 98,
            nameAr: 'البينة',
            nameEn: 'Al-Bayyinah',
            versesAr: [
              'لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ',
              'رَسُولٌۭ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًۭا مُّطَهَّرَةًۭ',
              'فِيهَا كُتُبٌۭ قَيِّمَةٌۭ',
              'وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ',
              'وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ',
              'إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ ۚ أُو۟لَـٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ',
              'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ',
              'جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّـٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًۭا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ'
            ],
            versesEn: [
              'The disbelievers from the People of the Book and the polytheists were not going to desist ˹from disbelief˺ until the clear proof came to them:',
              'a messenger from Allah, reciting scrolls of ˹utmost˺ purity,',
              'containing upright commandments.',
              'It was not until this clear proof came to the People of the Book that they became divided ˹about his prophethood˺—',
              'even though they were only commanded to worship Allah ˹alone˺ with sincere devotion to Him in all uprightness, establish prayer, and pay alms-tax. That is the upright Way.',
              'Indeed, those who disbelieve from the People of the Book and the polytheists will be in the Fire of Hell, to stay there forever. They are the worst of ˹all˺ beings.',
              'Indeed, those who believe and do good—they are the best of ˹all˺ beings.',
              'Their reward with their Lord will be Gardens of Eternity, under which rivers flow, to stay there for ever and ever. Allah is pleased with them and they are pleased with Him. This is ˹only˺ for those in awe of their Lord.'
            ],
          ),

          QuranSurah(
            id: 99,
            nameAr: 'الزلزلة',
            nameEn: 'Az-Zalzalah',
            versesAr: [
              'إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا',
              'وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا',
              'وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا',
              'يَوْمَئِذٍۢ تُحَدِّثُ أَخْبَارَهَا',
              'بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا',
              'يَوْمَئِذٍۢ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًۭا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ',
              'فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ',
              'وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍۢ شَرًّۭا يَرَهُۥ'
            ],
            versesEn: [
              'When the earth is shaken ˹in˺ its ultimate quaking,',
              'and when the earth throws out ˹all˺ its contents,',
              'and humanity cries, "What is wrong with it?"—',
              'on that Day the earth will recount everything,',
              'having been inspired by your Lord ˹to do so˺.',
              'On that Day people will proceed in separate groups to be shown ˹the consequences of˺ their deeds.',
              'So whoever does an atom\'s weight of good will see it.',
              'And whoever does an atom\'s weight of evil will see it.'
            ],
          ),

          QuranSurah(
            id: 100,
            nameAr: 'العاديات',
            nameEn: 'Al-Adiyat',
            versesAr: [
              'وَٱلْعَـٰدِيَـٰتِ ضَبْحًۭا',
              'فَٱلْمُورِيَـٰتِ قَدْحًۭا',
              'فَٱلْمُغِيرَٰتِ صُبْحًۭا',
              'فَأَثَرْنَ بِهِۦ نَقْعًۭا',
              'فَوَسَطْنَ بِهِۦ جَمْعًا',
              'إِنَّ ٱلْإِنسَـٰنَ لِرَبِّهِۦ لَكَنُودٌۭ',
              'وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌۭ',
              'وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ',
              'أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ',
              'وَحُصِّلَ مَا فِى ٱلصُّدُورِ',
              'إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍۢ لَّخَبِيرٌۢ'
            ],
            versesEn: [
              'By the galloping, panting horses,',
              'striking sparks of fire ˹with their hoofs˺,',
              'launching raids at dawn,',
              'stirring up ˹clouds of˺ dust,',
              'and penetrating into the heart of enemy lines!',
              'Surely humankind is ungrateful to their Lord—',
              'and they certainly attest to this—',
              'and they are truly extreme in their love of ˹worldly˺ gains.',
              'Do they not know that when the contents of the graves will be spilled out,',
              'and the secrets of the hearts will be laid bare—',
              'surely their Lord is All-Aware of them on that Day.'
            ],
          ),

          QuranSurah(
            id: 101,
            nameAr: 'القارعة',
            nameEn: 'Al-Qari\'ah',
            versesAr: [
              'ٱلْقَارِعَةُ',
              'مَا ٱلْقَارِعَةُ',
              'وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ',
              'يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ',
              'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ',
              'فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ',
              'فَهُوَ فِى عِيشَةٍۢ رَّاضِيَةٍۢ',
              'وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ',
              'فَأُمُّهُۥ هَاوِيَةٌۭ',
              'وَمَآ أَدْرَىٰكَ مَا هِيَهْ',
              'نَارٌ حَامِيَةٌۢ'
            ],
            versesEn: [
              'The Striking Disaster!',
              'What is the Striking Disaster?',
              'And what will make you realize what the Striking Disaster is?',
              '˹It is˺ the Day people will be like scattered moths,',
              'and the mountains will be like carded wool.',
              'So as for those whose scale is heavy ˹with good deeds˺,',
              'they will be in a life of bliss.',
              'And as for those whose scale is light,',
              'their home will be the abyss.',
              'And what will make you realize what that is?',
              '˹It is˺ a scorching Fire.'
            ],
          ),

          QuranSurah(
            id: 102,
            nameAr: 'التكاثر',
            nameEn: 'At-Takathur',
            versesAr: [
              'أَلْهَىٰكُمُ ٱلتَّكَاثُرُ',
              'حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ',
              'كَلَّا سَوْفَ تَعْلَمُونَ',
              'ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ',
              'كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ',
              'لَتَرَوُنَّ ٱلْجَحِيمَ',
              'ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ',
              'ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ'
            ],
            versesEn: [
              'Competition for more ˹gains˺ diverts you ˹from Allah˺,',
              'until you end up in ˹your˺ graves.',
              'But no! You will soon come to know.',
              'Again, no! You will soon come to know.',
              'Indeed, if you were to know ˹your fate˺ with certainty, ˹you would have acted differently˺.',
              '˹But˺ you will surely see the Hellfire.',
              'Again, you will surely see it with the eye of certainty.',
              'Then, on that Day, you will definitely be questioned about ˹your worldly˺ pleasures.'
            ],
          ),

          QuranSurah(
            id: 103,
            nameAr: 'العصر',
            nameEn: 'Al-Asr',
            versesAr: [
              'وَٱلْعَصْرِ',
              'إِنَّ ٱلْإِنسَـٰنَ لَفِى خُسْرٍ',
              'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ'
            ],
            versesEn: [
              'By the ˹passage of˺ time!',
              'Surely humanity is in ˹grave˺ loss,',
              'except those who have faith, do good, and urge each other to the truth, and urge each other to perseverance.'
            ],
          ),

          QuranSurah(
            id: 104,
            nameAr: 'الهمزة',
            nameEn: 'Al-Humazah',
            versesAr: [
              'وَيْلٌۭ لِّكُلِّ هُمَزَةٍۢ لُّمَزَةٍ',
              'ٱلَّذِى جَمَعَ مَالًۭا وَعَدَّدَهُۥ',
              'يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ',
              'كَلَّا ۖ لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ',
              'وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ',
              'نَارُ ٱللَّهِ ٱلْمُوقَدَةُ',
              'ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ',
              'إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌۭ',
              'فِى عَمَدٍۢ مُّمَدَّدَةٍۭ'
            ],
            versesEn: [
              'Woe to every backbiter, slanderer,',
              'who amasses wealth ˹greedily˺ and counts it ˹repeatedly˺,',
              'thinking that their wealth will make them immortal!',
              'Not at all! Such a person will certainly be tossed into the Crusher.',
              'And what will make you realize what the Crusher is?',
              '˹It is˺ Allah\'s kindled Fire,',
              'which rages over the hearts.',
              'It will be sealed over them,',
              '˹tightly secured˺ with long braces.'
            ],
          ),

          QuranSurah(
            id: 105,
            nameAr: 'الفيل',
            nameEn: 'Al-Fil',
            versesAr: [
              'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَـٰبِ ٱلْفِيلِ',
              'أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍۢ',
              'وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ',
              'تَرْمِيهِم بِحِجَارَةٍۢ مِّن سِجِّيلٍۢ',
              'فَجَعَلَهُمْ كَعَصْفٍۢ مَّأْكُولٍۭ'
            ],
            versesEn: [
              'Have you not seen ˹O Prophet˺ how your Lord dealt with the Army of the Elephant?',
              'Did He not frustrate their scheme?',
              'For He sent against them flocks of birds,',
              'that pelted them with stones of baked clay,',
              'leaving them like chewed up straw.'
            ],
          ),
          QuranSurah(
  id: 106,
  nameAr: 'قريش',
  nameEn: 'Quraysh',
  versesAr: [
    'لِإِيلَـٰفِ قُرَيْشٍ',
    'إِۦلَـٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ',
    'فَلْيَعْبُدُوا۟ رَبَّ هَـٰذَا ٱلْبَيْتِ',
    'ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ'
  ],
  versesEn: [
    '˹At least˺ for ˹the favour of˺ making Quraysh habitually secure—',
    'secure in their trading caravan ˹to Yemen˺ in the winter and ˹Syria˺ in the summer—',
    'let them worship the Lord of this ˹Sacred˺ House,',
    'Who has fed them against hunger and made them secure against fear.'
  ],
),

QuranSurah(
  id: 107,
  nameAr: 'الماعون',
  nameEn: 'Al-Ma\'un',
  versesAr: [
    'أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ',
    'فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ',
    'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ',
    'فَوَيْلٌۭ لِّلْمُصَلِّينَ',
    'ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ',
    'ٱلَّذِينَ هُمْ يُرَآءُونَ',
    'وَيَمْنَعُونَ ٱلْمَاعُونَ'
  ],
  versesEn: [
    'Have you seen the one who denies the ˹final˺ Judgment?',
    'That is the one who repulses the orphan,',
    'and does not encourage the feeding of the poor.',
    'So woe to those ˹hypocrites˺ who pray',
    'yet are unmindful of their prayers;',
    'those who ˹only˺ show off,',
    'and refuse to give ˹even the simplest˺ aid.'
  ],
),

QuranSurah(
  id: 108,
  nameAr: 'الكوثر',
  nameEn: 'Al-Kawthar',
  versesAr: [
    'إِنَّآ أَعْطَيْنَـٰكَ ٱلْكَوْثَرَ',
    'فَصَلِّ لِرَبِّكَ وَٱنْحَرْ',
    'إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ'
  ],
  versesEn: [
    'Indeed, We have granted you ˹O Prophet˺ abundant goodness.',
    'So pray and sacrifice to your Lord ˹alone˺.',
    'Only the one who hates you is truly cut off ˹from any goodness˺.'
  ],
),

QuranSurah(
  id: 109,
  nameAr: 'الكافرون',
  nameEn: 'Al-Kafirun',
  versesAr: [
    'قُلْ يَـٰٓأَيُّهَا ٱلْكَـٰفِرُونَ',
    'لَآ أَعْبُدُ مَا تَعْبُدُونَ',
    'وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ',
    'وَلَآ أَنَا۠ عَابِدٌۭ مَّا عَبَدتُّمْ',
    'وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ',
    'لَكُمْ دِينُكُمْ وَلِىَ دِينِ'
  ],
  versesEn: [
    'Say, ˹O Prophet,˺ "O you disbelievers!',
    'I do not worship what you worship,',
    'nor do you worship what I worship.',
    'I will never worship what you worship,',
    'nor will you ever worship what I worship.',
    'You have your way, and I have my Way."'
  ],
),

QuranSurah(
  id: 110,
  nameAr: 'النصر',
  nameEn: 'An-Nasr',
  versesAr: [
    'إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ',
    'وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًۭا',
    'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا'
  ],
  versesEn: [
    'When Allah\'s ˹ultimate˺ help comes and the victory ˹over Mecca is achieved˺,',
    'and you ˹O Prophet˺ see the people embracing Allah\'s Way in crowds,',
    'then glorify the praises of your Lord and seek His forgiveness, for certainly He is ever Accepting of Repentance.'
  ],
),

QuranSurah(
  id: 111,
  nameAr: 'المسد',
  nameEn: 'Al-Masad',
  versesAr: [
    'تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ',
